"""Feature-gated package resolution constraint checking.

assess_selection(request, roots, selected) validates one complete choice and,
when valid, returns the public evaluation dict (active_dependencies,
prior_deltas, score). It returns None for any invalid complete choice.
"""


def _fits(version, low, high):
    value = tuple(version)
    return (low is None or tuple(low) <= value) and (high is None or value < tuple(high))


def _active(features, dep):
    return dep["feature"] is None or dep["feature"] in features


def assess_selection(request, roots, selected):
    config = request["config"]
    features = set(config["features"])
    catalog = {
        p["package"]: {tuple(v["version"]): v for v in p["versions"]}
        for p in request["catalog"]
    }

    # Normalize selected to tuples; reject unoffered selections.
    sel = {}
    for pkg, ver in selected.items():
        if pkg not in catalog:
            return None
        key = tuple(ver)
        if key not in catalog[pkg]:
            return None
        sel[pkg] = key

    # Every root must be selected within its interval.
    for r in roots:
        pkg = r["package"]
        if pkg not in sel:
            return None
        if not _fits(sel[pkg], r["min"], r["max"]):
            return None

    # Required closure starting from roots.
    closure = {r["package"] for r in roots}
    changed = True
    while changed:
        changed = False
        for pkg in list(closure):
            if pkg not in sel:
                return None
            for d in catalog[pkg][sel[pkg]]["deps"]:
                if _active(features, d) and d["kind"] == "required":
                    if d["package"] not in closure:
                        closure.add(d["package"])
                        changed = True

    # No package outside the required closure may be selected.
    if closure != set(sel):
        return None

    # Every active dependency (required and peer) must be satisfied.
    edges = []
    for pkg, ver in sel.items():
        for d in catalog[pkg][ver]["deps"]:
            if not _active(features, d):
                continue
            target = d["package"]
            if target not in sel or not _fits(sel[target], d["min"], d["max"]):
                return None
            edges.append(
                dict(source=pkg, target=target, kind=d["kind"], feature=d["feature"])
            )

    # Prior deltas over the union of prior and selected.
    prior = {k: tuple(v) for k, v in config["prior"].items()}
    changed_pkgs = [
        k for k in prior.keys() | sel.keys() if prior.get(k) != sel.get(k)
    ]
    deltas = [
        dict(
            package=k,
            prior=list(prior[k]) if k in prior else None,
            selected=list(sel[k]) if k in sel else None,
        )
        for k in sorted(changed_pkgs)
    ]

    freshness = sum(100 * v[0] + 10 * v[1] + v[2] for v in sel.values())

    return dict(
        active_dependencies=edges,
        prior_deltas=deltas,
        score=dict(changes=len(changed_pkgs), freshness=freshness),
    )

"""Exact complete-assignment search and objective optimization.

select_versions(request, roots, assess) enumerates every distinct feasible
complete assignment exactly once, counts them, and returns the assignment that
minimizes changes then maximizes freshness.
"""


def select_versions(request, roots, assess):
    catalog = request["catalog"]
    packages = [p["package"] for p in catalog]
    versions = {
        p["package"]: [tuple(v["version"]) for v in p["versions"]]
        for p in catalog
    }

    feasible_count = 0
    best = None
    best_eval = None

    def rec(i, selected):
        nonlocal feasible_count, best, best_eval
        if i == len(packages):
            ev = assess(roots, selected)
            if ev is not None:
                feasible_count += 1
                score = ev["score"]
                key = (score["changes"], -score["freshness"])
                if best is None or key < best:
                    best = key
                    best_eval = ev
                    best = key
                    best_selected = dict(selected)
            return
        pkg = packages[i]
        for ver in versions[pkg]:
            selected[pkg] = list(ver)
            rec(i + 1, selected)
        selected.pop(pkg, None)

    best_selected = {}
    rec(0, {})

    if feasible_count == 0:
        return dict(feasible_count=0, selected={}, evaluation=None)

    return dict(
        feasible_count=feasible_count,
        selected=best_selected,
        evaluation=best_eval,
    )

