from packages.analysis.selection_constraints import assess_selection
from packages.analysis.global_selection import select_versions


def _blocked():
    return dict(
        status="blocked",
        selected=[],
        active_dependencies=[],
        prior_deltas=[],
        score=None,
        feasible_count=0,
        minimal_root_conflict=[],
    )


def _minimal_root_conflict(request):
    roots = request["config"]["roots"]
    n = len(roots)

    def infeasible(subset):
        return select_versions(request, subset, assess_selection)["feasible_count"] == 0

    for size in range(1, n + 1):
        for mask in range(1 << n):
            if bin(mask).count("1") != size:
                continue
            subset = [roots[i] for i in range(n) if mask & (1 << i)]
            if infeasible(subset):
                return [r["package"] for r in subset]
    return []


def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    request = payload["request"]
    roots = request["config"]["roots"]

    result = select_versions(request, roots, assess_selection)

    if result["feasible_count"] == 0:
        report = _blocked()
        report["minimal_root_conflict"] = _minimal_root_conflict(request)
        return report

    ev = result["evaluation"]
    selected = [
        dict(package=k, version=list(v))
        for k, v in sorted(result["selected"].items())
    ]
    return dict(
        status="ready",
        selected=selected,
        active_dependencies=ev["active_dependencies"],
        prior_deltas=ev["prior_deltas"],
        score=ev["score"],
        feasible_count=result["feasible_count"],
        minimal_root_conflict=[],
    )


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)

